-- The two checklists published on 2026-11-08: Making the Commute Less of a
-- Grind (Commuting) and Putting Money Aside When It Feels Pointless (Saving).
-- Generated by `python3 tools/checklists_sql.py making-the-commute-less-of-a-grind
-- putting-money-aside-when-it-feels-pointless`; the repo copy in
-- data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('making-the-commute-less-of-a-grind', 'Making the Commute Less of a Grind', 'For a journey you make most days and have stopped thinking about. It decides what the time is for, buys back five minutes, keeps work email shut until you arrive, and marks the end of the trip so the day does not blur into it.', 'Commuting', '["Pick one thing the journey is for — reading, music or nothing, but decide rather than drift.", "Leave five minutes earlier than feels necessary — five minutes buys back the tone of the morning.", "Keep work email shut until you arrive — answering on the move means arriving already behind.", "Have one thing that marks the end of the journey — a coffee, a walk round the block, a changed shirt.", "Download what you need the night before — hunting for signal is its own small misery.", "Keep water and something to eat in the bag — hungry and stuck is a worse kind of stuck.", "Work out what delay you can absorb and plan for it — a route with no slack fails every week.", "Use the way home to put the day down — arriving with work still running costs you the evening.", "Ask once a month whether this journey is worth it — a commute you never question quietly sets your life."]'::jsonb, 'daily', array['Work', 'Habits', 'Stress']::text[], 1, '2026-11-08T16:00:00+00:00'::timestamptz),
  ('putting-money-aside-when-it-feels-pointless', 'Putting Money Aside When It Feels Pointless', 'For when setting money aside feels too slow to be worth it. It starts with an amount you will not miss, moves it on payday rather than whatever is left, names what it protects you from, and restarts the week after you raid it.', 'Saving', '["Start with an amount that feels almost silly — a sum you will not miss is a sum you will keep.", "Move it on the day you are paid — what is left at the end is never what you planned.", "Put it somewhere slightly annoying to reach — one extra step is usually friction enough.", "Name the account after what it is for — a car-repair fund gets raided less than a savings one.", "Write down what this is actually protecting you from — vague saving always loses to a concrete want.", "Count it once a month rather than once a week — watching it barely move is discouraging by design.", "Put any windfall in before you adapt to it — a refund spends itself if it sits in the current account.", "Spend some of it on the thing you saved for — money that is never spent stops feeling real.", "Restart the week after you raid it — stopping for good is the only version that actually fails."]'::jsonb, 'weekly', array['Money', 'Habits', 'Motivation']::text[], 1, '2026-11-08T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
